#define \u0411\u0406\u0422\u041a\u0410\u0421\u0422(dest_type, source_type, source_val) \
  (((union {                                        \
     source_type src;                               \
     dest_type dst;                                 \
   }){.src = (source_val)})                         \
       .dst)

double fmod(double x, double y);

